// application/OrderService.ts
import { OrderRepository } from '../infra/OrderRepository';
import { InvoiceRepository } from '../infra/InvoiceRepository';

export class OrderService {
  constructor(
    private orderRepo: OrderRepository,
    private invoiceRepo: InvoiceRepository
  ) {}

  async getOrder(id: string) {
    return this.orderRepo.findById(id);
  }

  async getOrdersByCustomer(customerId: string) {
    return this.orderRepo.findByCustomerId(customerId);
  }

  async createOrder(dto: CreateOrderDto) {
    return this.orderRepo.save({ ...dto, status: 'pending', createdAt: new Date() });
  }

  async confirmOrder(orderId: string, userId: string) {
    const order = await this.orderRepo.findById(orderId);
    const invoices = await this.invoiceRepo.findByOrderId(orderId);
    if (order.status !== 'pending') throw new Error('Not pending');
    if (invoices.some((i: any) => i.status === 'overdue')) throw new Error('Has overdue invoices');
    if (order.totalAmount > 10000 && !order.approvalId) throw new Error('Needs approval');
    order.status = 'confirmed';
    order.confirmedAt = new Date();
    order.confirmedBy = userId;
    return this.orderRepo.save(order);
  }

  async getInvoicesForOrder(orderId: string) {
    return this.invoiceRepo.findByOrderId(orderId);
  }

  async cancelOrder(id: string) {
    const order = await this.orderRepo.findById(id);
    order.status = 'cancelled';
    return this.orderRepo.save(order);
  }
}
